CREATE PROCEDURE CLAIMS.CONSTRAINT_CONTRADICTION
(
    IN P_VALUE DECIMAL(10,2),
    OUT P_RESULT VARCHAR(20)
)
LANGUAGE SQL
BEGIN
    SET P_RESULT = 'DEFAULT';
    IF P_VALUE > 10 AND P_VALUE <= 10 THEN
        SET P_RESULT = 'IMPOSSIBLE';
    ELSE
        SET P_RESULT = 'POSSIBLE';
    END IF;
END
